def scenario_count_directives(ts_count, content_based_phrase: str):
    """Normalize a scenario count into display text plus hard generation rules.

    Returns (count_display, quantity_rule, stop_rule, has_exact_count).
    """
    try:
        n = int(ts_count) if ts_count not in (None, "", False) else 0
    except (ValueError, TypeError):
        n = 0
    if n > 100:
        n = 100
    if n > 0:
        quantity_rule = (
            f"Generate EXACTLY {n} scenario(s) in total for the requested type(s). "
            "Do not generate more. Do not generate fewer. "
            "This explicit count is a hard target. It overrides inventory completeness, "
            "default 45-50 counts, and 'as many as content supports'."
        )
        stop_rule = (
            f"Stop when EXACTLY {n} unique scenarios are produced. "
            f"Once {n} is reached, remaining inventory items MUST be skipped. "
            f"Do not stop before {n} unless the source content cannot support more unique scenarios."
        )
        return n, quantity_rule, stop_rule, True
    quantity_rule = (
        f"No explicit test-case count was requested. {content_based_phrase}"
    )
    stop_rule = (
        "Only stop when every item in the coverage inventory is checked off, "
        "without padding duplicates."
    )
    return content_based_phrase, quantity_rule, stop_rule, False


